import mpmath

mpmath.mp.dps = 50


def boys_mp(n, T):
    if T == 0:
        return mpmath.mpf(1) / (2 * n + 1)
    a = mpmath.mpf(n) + mpmath.mpf(1) / 2
    return mpmath.gammainc(a, 0, T) / (2 * mpmath.mpf(T) ** a)


