    lo, hi = 1e-300, 1.0 / r0  # the root below the threshold S = 1/R0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if np.log(s0 / mid) - r0 * (1.0 - mid) > 0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


